import 'package:geolocator/geolocator.dart'; import '../models/emergency.dart';
class LocationService { Future<LocationResult> current() async { if(!await Geolocator.isLocationServiceEnabled())return const LocationResult(error:'Location services are disabled'); var p=await Geolocator.checkPermission(); if(p==LocationPermission.denied) p=await Geolocator.requestPermission(); if(p==LocationPermission.denied||p==LocationPermission.deniedForever)return const LocationResult(error:'Location permission is unavailable'); try {final x=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high,timeLimit:Duration(seconds:12)));return LocationResult(latitude:x.latitude,longitude:x.longitude,source:'current');}catch(_){return const LocationResult(error:'Current location timed out or is unavailable');} } }
